  ('3897e8f7-a666-4523-a694-edd6552a540f', '5d7ada6c-e8bc-44f4-8fce-3d5b4d4069a4', $$belastingen buiten beschouwing; Motherman nv deed op 1 oktober 2024 een aandelenemissie$$,
